// Combine GitHub data into a structured summary
const commits = $input.all().filter(item => item.json.sha).map(item => ({
  message: item.json.commit?.message || item.json.message || '',
  author: item.json.commit?.author?.name || item.json.author?.login || 'unknown',
  date: item.json.commit?.author?.date || '',
  sha: (item.json.sha || '').substring(0, 7),
}));

const issues = $input.all().filter(item => item.json.number && !item.json.pull_request).map(item => ({
  title: item.json.title || '',
  number: item.json.number,
  state: item.json.state || 'closed',
  closed_at: item.json.closed_at || '',
  labels: (item.json.labels || []).map(l => l.name).join(', '),
}));

const prs = $input.all().filter(item => item.json.pull_request || item.json.merged_at).map(item => ({
  title: item.json.title || '',
  number: item.json.number,
  merged: !!item.json.merged_at,
  author: item.json.user?.login || 'unknown',
  merged_at: item.json.merged_at || item.json.closed_at || '',
})).filter(pr => pr.merged);

const lang = $env.SUMMARY_LANGUAGE || 'EN';

const prompt_en = `Generate a concise weekly dev summary for a GitHub repository.

COMMITS THIS WEEK (${commits.length}):
${commits.slice(0, 30).map(c => `- ${c.message} (${c.sha} by ${c.author})`).join('\n')}

CLOSED ISSUES THIS WEEK (${issues.length}):
${issues.slice(0, 20).map(i => `- #${i.number}: ${i.title} [${i.labels}]`).join('\n')}

MERGED PRs THIS WEEK (${prs.length}):
${prs.slice(0, 20).map(p => `- #${p.number}: ${p.title} (by ${p.author})`).join('\n')}

Write a narrative summary in Markdown with these sections:
1. **Highlights** - Top 3 most impactful changes
2. **What shipped** - Features and fixes that went out
3. **What's in progress** - Based on open issues context
4. **Stats** - commits, PRs merged, issues closed
5. **Contributors** - Who contributed this week

Keep it concise but informative. Use bullet points.`;

const prompt_fr = `Génère un résumé hebdomadaire de développement pour un dépôt GitHub.

COMMITS CETTE SEMAINE (${commits.length}):
${commits.slice(0, 30).map(c => `- ${c.message} (${c.sha} par ${c.author})`).join('\n')}

ISSUES FERMÉES CETTE SEMAINE (${issues.length}):
${issues.slice(0, 20).map(i => `- #${i.number}: ${i.title} [${i.labels}]`).join('\n')}

PRs FUSIONNÉS CETTE SEMAINE (${prs.length}):
${prs.slice(0, 20).map(p => `- #${p.number}: ${p.title} (par ${p.author})`).join('\n')}

Écris un résumé narratif en Markdown avec ces sections:
1. **Points forts** - Top 3 changements les plus impactants
2. **Ce qui a été livré** - Fonctionnalités et correctifs publiés
3. **En cours** - Basé sur le contexte des issues ouvertes
4. **Statistiques** - commits, PRs fusionnés, issues fermées
5. **Contributeurs** - Qui a contribué cette semaine

Sois concis mais informatif. Utilise des puces.`;

const prompt = lang === 'FR' ? prompt_fr : prompt_en;

return [{
  json: {
    prompt: prompt,
    commits_count: commits.length,
    issues_count: issues.length,
    prs_count: prs.length,
    language: lang,
  }
}];

const response = $input.first().json;
const summary = response.content?.[0]?.text || 'No summary generated.';
const repo = $env.GITHUB_REPO || 'unknown/repo';
const now = new Date().toISOString().split('T')[0];

const header = `# Weekly Dev Summary\n\n**Repo:** ${repo}\n**Week ending:** ${now}\n\n---\n\n`;
const footer = `\n\n---\n_Generated automatically by n8n + Claude Sonnet_`;

return [{
  json: {
    summary: header + summary + footer,
    repo: repo,
    date: now,
  }
}];
